document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".hamburger"),t=document.querySelector(".nav-links"),o=document.querySelectorAll(".nav-link");e.addEventListener("click",()=>{e.classList.toggle("active"),t.classList.toggle("active"),document.body.style.overflow=t.classList.contains("active")?"hidden":"auto"}),o.forEach(o=>{o.addEventListener("click",()=>{e.classList.remove("active"),t.classList.remove("active"),document.body.style.overflow="auto"})});const s=document.getElementById("header");let c=!1;window.addEventListener("scroll",()=>{c||(window.requestAnimationFrame(()=>{window.scrollY>50?s.classList.add("scrolled"):s.classList.remove("scrolled"),c=!1}),c=!0)},{passive:!0});const r=document.querySelectorAll("section"),n=new IntersectionObserver(e=>{e.forEach(e=>{if(e.isIntersecting){o.forEach(e=>{e.classList.remove("active")});const t=e.target.getAttribute("id"),s=document.querySelector(`.nav-link[href="#${t}"]`);s&&s.classList.add("active")}})},{root:null,rootMargin:"-20% 0px -60% 0px",threshold:0});r.forEach(e=>{n.observe(e)});const a=document.querySelectorAll("video"),l=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting?e.target.play().catch(()=>{}):e.target.pause()})},{threshold:.3});a.forEach(e=>l.observe(e))});